solutionCode.cpp:
#include <iostream>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    // Entre deux int, / donne le quotient entier et % le reste.
    cout << n / k << "\n";
    cout << n % k << "\n";
    return 0;
}

